-- ============================================================
-- V1.59: 宠物用品 AI 客服学习知识库种子数据
-- 一级分类: 宠物用品 (pet_supplies)
-- 二级分类: pet_food / pet_toys / pet_clothes / pet_supplies_misc / pet_aquarium
-- 规模: 5 个二级分类 × 30 条 = 150 条高价值 Q&A
-- 风格: 闲鱼真实买家刁钻提问 + 销冠级化解话术, 突出正品安全与宠物健康
-- 场景覆盖: 宠物年龄/体重适用、成分、是否正品、保质期、尺寸、是否可水洗、是否会过敏
-- 幂等说明: content_hash = MD5(question + answer), 重复执行会因唯一键冲突跳过
--          (如需可重复执行, 可在外层包 NOT EXISTS 或 INSERT IGNORE)
-- learn_batch_id: seed-v1.59
-- source_type: seed
-- ============================================================

-- ============ 1. 宠物食品 pet_food (30 条) ============
INSERT INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.59', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'pet_food' AS code, '这款猫粮保质期还有多久?别给我发临期的' AS question, '亲,目前发货批次生产日期是2个月内,保质期18个月,到货后剩余保质期16个月以上,绝对不是临期。发货前我会拍照生产日期给您确认,不满意直接退,运费我承担。猫粮新鲜度直接影响适口性和营养,我家绝不做临期清仓的事。建议开封后45天内喂完,密封避光保存。两袋起拍减15元,囤着吃更划算,要不要凑单?' AS answer, '猫粮,保质期,临期,生产日期,新鲜' AS tags, '猫粮保质期承诺与新鲜度话术' AS source_summary, 88 AS score
  UNION ALL SELECT 'pet_food', '我家猫3个月大能吃这款猫粮吗?', '亲,这款是全期猫粮,3个月以上的幼猫可以吃,颗粒偏小适合幼猫咀嚼。不过3个月刚断奶不久,建议先用温水把粮泡软再喂,过渡一周后逐步换成干粮,让肠胃有个适应过程。如果是2个月刚断奶的幼猫,建议选专用幼猫粮,我店里也有,蛋白质更高更适合成长期。两袋凑单减20,成长期营养跟得上,需要我推荐吗?' AS answer, '猫粮,幼猫,全期,泡软,断奶' AS tags, '幼猫全期粮适用与过渡话术' AS source_summary, 90 AS score
  UNION ALL SELECT 'pet_food', '网上假猫粮太多,你怎么证明是正品?', '亲理解您的顾虑,宠物食品假货确实多,猫吃进肚子的东西马虎不得。我家有三道防伪:第一,包装侧面有溯源二维码,扫码可查批次和流通渠道;第二,可提供供应商授权书和进货凭证;第三,支持专柜验货,假一赔十。您收到货先别拆,扫码验真后再喂。新粉关注店铺领10元券,正品保障让您放心囤。' AS answer, '猫粮,正品,防伪,溯源,假一赔十' AS tags, '猫粮正品三道防伪话术' AS source_summary, 92 AS score
  UNION ALL SELECT 'pet_food', '第一次换这款粮怎么过渡?怕猫拉肚子', '亲,换粮一定要用7天过渡法,不能直接换,否则猫容易拉肚子。具体方法:第一天到第二天新旧粮比例1比3,第三天到第四天1比1,第五天到第六天3比1,第七天全换新粮。过渡期观察便便,如果变软就放慢节奏。这款粮添加了益生菌,有助于肠胃适应。如果过渡期拉肚子严重,停粮联系我,7天内可退。' AS answer, '猫粮,换粮,过渡,拉肚子,益生菌' AS tags, '换粮7天过渡法话术' AS source_summary, 85 AS score
  UNION ALL SELECT 'pet_food', '能发一下成分表吗?想看看肉含量', '亲,这款猫粮粗蛋白36%,粗脂肪14%,肉含量65%以上,主蛋白来源是鲜鸡肉和鸡肉粉,无谷物添加。成分表前五位是鲜鸡肉、鸡肉粉、红薯、鸡油、鱼油,都是优质原料。粗蛋白36%属于中高端水平,适合室内猫。如果您想要更高蛋白,我店还有42%的无谷高蛋白款,价格贵20元,需要看看吗?' AS answer, '猫粮,成分,肉含量,蛋白,无谷' AS tags, '猫粮成分表与肉含量话术' AS source_summary, 86 AS score
  UNION ALL SELECT 'pet_food', '我家狗对鸡肉过敏,有别的口味吗?', '亲,这款是鸡肉味的,过敏的话不合适。店里还有三文鱼和羊肉口味,羊肉蛋白致敏性更低,适合敏感肠胃和过敏体质的狗狗。您拍的时候备注换羊肉味,我给您发对应的。过敏体质建议先买小包装试一周,无反应再囤大包,试错成本最低。店里羊味粮今天有满199减30,凑个零食正好,要不要一起?' AS answer, '狗粮,过敏,鸡肉,羊肉,换味' AS tags, '狗粮过敏体质换味话术' AS source_summary, 88 AS score
  UNION ALL SELECT 'pet_food', '猫粮开封后能放多久?会不会变质?', '亲,猫粮开封后最佳食用期是45天,放久了会氧化走味,营养流失,猫可能不吃了。建议您:第一,用密封夹夹紧袋口,挤出空气;第二,放在阴凉干燥处,避免阳光直射和高温;第三,别倒进塑料桶储存,塑料会渗油变质,原袋最好。如果囤了大包吃不完,建议分装小袋密封冷冻。开封后有异味或发霉立即停喂,联系我退换。' AS answer, '猫粮,开封,保存,变质,密封' AS tags, '猫粮开封保存与防变质话术' AS source_summary, 82 AS score
  UNION ALL SELECT 'pet_food', '这款是无谷粮吗?含不含谷物?', '亲,这款是无谷配方,不含玉米、小麦、大豆等谷物,用红薯和豌豆做碳水化合物来源,更低敏更易消化。无谷粮的好处是减少过敏风险,便便也不那么臭。如果您家猫肠胃敏感或容易软便,无谷粮是首选。店里还有含谷款的日常粮,价格便宜20元,肠胃好的猫也能吃。您家猫什么情况?我帮您推荐合适的。' AS answer, '猫粮,无谷,谷物,低敏,消化' AS tags, '无谷粮低敏与含谷款对比话术' AS source_summary, 84 AS score
  UNION ALL SELECT 'pet_food', '我家狗25斤,这款粮适合吗?', '亲,25斤属于中型犬,这款粮完全适合,蛋白质28%能满足中型犬日常需求。25斤的狗每天喂食量大约200到250克,具体看运动量,包装袋上有喂食量表。建议分两餐喂,早上一半晚上一半,别一次喂太多容易胀气。这款粮颗粒中等大小,25斤的狗嚼着刚好。店里大包装5kg装更划算,够吃20天,要不要拍大包?' AS answer, '狗粮,中型犬,体重,喂食量,颗粒' AS tags, '中型犬狗粮适用与喂食话术' AS source_summary, 80 AS score
  UNION ALL SELECT 'pet_food', '罐头开封后怎么保存?能放几天?', '亲,罐头开封后必须冷藏保存,放冰箱保鲜层,最多放2到3天,超过就别喂了容易变质。建议:第一,吃剩的连罐头盒一起用保鲜膜封好放冰箱;第二,喂之前回温到室温,别喂冰冷的猫吃了会拉肚子;第三,别用金属勺子挖容易氧化,用塑料或木勺。最好买小罐80克的,一顿吃完不浪费。店里80克小罐12罐装减20,要不要凑单?' AS answer, '罐头,开封,冷藏,保存,变质' AS tags, '罐头开封冷藏保存话术' AS source_summary, 83 AS score
  UNION ALL SELECT 'pet_food', '这款零食添加剂多吗?有诱食剂吗?', '亲,这款冻干零食配料表只有一样——鲜鸡肉,单一蛋白无添加,没有诱食剂、防腐剂、色素。冻干工艺是零下40度冷冻干燥,锁住营养不流失,复水后就是纯肉。猫爱吃是因为肉香,不是诱食剂。看配料表越短越干净,这款只有一个成分,比人吃的零食还干净。如果猫挑食,这款冻干撒在猫粮上是绝佳诱食,纯天然的。' AS answer, '零食,添加剂,诱食剂,冻干,单一蛋白' AS tags, '零食无添加与冻干话术' AS source_summary, 85 AS score
  UNION ALL SELECT 'pet_food', '这款是主粮还是零食?能当饭吃吗?', '亲,这款是主食罐头,营养均衡可以当主粮吃,不是零食罐。区分方法:主食罐配料表含牛磺酸、维生素等全面营养,零食罐只有肉。主食罐可以天天喂,零食罐一周最多两三次。这款主食罐粗蛋白11%,符合AAFCO标准,能完全替代猫粮。建议粮罐搭配喂,猫吃得更开心,水分也够。店里6罐装减15,粮罐混喂更划算。' AS answer, '罐头,主粮,零食,主食罐,营养' AS tags, '主食罐与零食罐区分话术' AS source_summary, 78 AS score
  UNION ALL SELECT 'pet_food', '我家猫12岁了,老年猫能吃这款吗?', '亲,12岁属于老年猫了,这款有老年猫专用配方,蛋白质适度降低到30%,减轻肾脏负担,同时添加了关节保护成分软骨素和葡萄糖胺,适合老年猫。老年猫消化能力下降,建议:第一,少食多餐一天3到4次;第二,用温水泡软方便咀嚼;第三,定期体检关注肾功能。店里老年猫粮小包装试吃装5元,先试试口性,合适再回购。' AS answer, '猫粮,老年猫,关节,肾脏,少食多餐' AS tags, '老年猫粮专用配方话术' AS source_summary, 87 AS score
  UNION ALL SELECT 'pet_food', '我家猫太胖了,有减肥粮吗?', '亲,这款是室内猫轻体配方,脂肪含量降到9%,比普通粮低40%,添加了左旋肉碱帮助燃脂,同时纤维素高增加饱腹感,猫吃得饱还不胖。减肥不能饿着,要靠低脂高纤。建议每天喂食量减少20%,配合逗猫棒运动,3个月能瘦半斤到一斤。减肥别急,快速减重会脂肪肝。店里轻体粮2kg装减10元,够吃一个月,要不要试试?' AS answer, '猫粮,减肥,轻体,低脂,左旋肉碱' AS tags, '猫减肥粮轻体配方话术' AS source_summary, 86 AS score
  UNION ALL SELECT 'pet_food', '这款粮含诱食剂吗?怕猫上瘾不吃别的', '亲,正规品牌粮不含人工诱食剂,猫爱吃是因为原料好肉含量高,天然肉香。诱食剂是低端粮用的,猫咪上瘾后挑食。这款粮的适口性来自65%真肉含量和鸡油,不是添加剂。判断方法:看配料表有没有宠物饲料复合调味料,有的就是诱食剂。这款没有,放心喂。如果猫现在挑食,可以用这款粮掺着旧粮过渡,慢慢戒掉诱食剂依赖。' AS answer, '猫粮,诱食剂,上瘾,挑食,调味料' AS tags, '猫粮无诱食剂与挑食戒断话术' AS source_summary, 88 AS score
  UNION ALL SELECT 'pet_food', '批号和产地能告诉我吗?我想查一下', '亲,这款猫粮产地是山东青岛,工厂代工多个知名品牌。批号在包装背面底部,格式是年月日加批次,比如20260728A1。您扫码溯源可以看到生产日期、批次、原料来源。每个批次我都会记录,有问题随时追溯。发货前我会拍照批号给您确认,收货后扫码验真,双重保障。正品行货,假一赔十,放心拍。' AS answer, '猫粮,批号,产地,溯源,工厂' AS tags, '猫粮批号产地追溯话术' AS source_summary, 75 AS score
  UNION ALL SELECT 'pet_food', '我家猫怀孕了,能吃这款粮吗?', '亲,怀孕母猫需要高蛋白高钙,这款是全期粮可以吃,但建议换成幼猫粮或母猫专用粮,蛋白质更高营养更全面,满足孕期和哺乳期需求。怀孕后期猫食量会增加20%到30%,别限量。哺乳期更是要敞开喂,猫妈妈吃得好小猫才健康。店里幼猫粮哺乳期专用款减20元,一袋够整个孕期加哺乳期,需要我推荐吗?' AS answer, '猫粮,怀孕,母猫,哺乳,高蛋白' AS tags, '怀孕母猫营养与专用粮话术' AS source_summary, 90 AS score
  UNION ALL SELECT 'pet_food', '我家猫肠胃敏感经常软便,能吃吗?', '亲,肠胃敏感的猫建议选单一蛋白加无谷配方的粮,这款正好符合,主蛋白只有鸡肉一种,无谷低敏,还添加了益生菌和果寡糖,帮助肠道健康。建议换粮时7天过渡,同时补充宠物益生菌,便便会成型。如果软便严重,先停粮喂白水煮鸡胸肉3天让肠胃休息,再慢慢换粮。店里益生菌搭配粮一起拍减10元,肠胃弱的猫必备。' AS answer, '猫粮,肠胃敏感,软便,益生菌,单一蛋白' AS tags, '肠胃敏感猫粮与益生菌话术' AS source_summary, 87 AS score
  UNION ALL SELECT 'pet_food', '这款粮颗粒多大?小型犬能嚼动吗', '亲,这款颗粒直径约8毫米,小型犬完全能嚼动,我家的泰迪吃得很好。小型犬不建议喂大颗粒粮,嚼不碎容易整个吞,消化不良。如果是很小的狗比如吉娃娃,建议拍小颗粒款直径5毫米,更容易嚼。大型犬反而要大颗粒,小颗粒不够嚼,牙结石多。您家狗什么品种多重?我帮您选合适的颗粒大小。' AS answer, '狗粮,颗粒,小型犬,咀嚼,牙结石' AS tags, '狗粮颗粒大小与体型话术' AS source_summary, 80 AS score
  UNION ALL SELECT 'pet_food', '支持收到货验货再确认吗?', '亲,闲鱼支持验货后确认收货。您收到猫粮后:第一,先看外包装是否完好;第二,扫码验真查溯源;第三,拆袋看颗粒颜色气味;第四,给猫试吃观察反应。如果有任何问题,48小时内联系我,支持7天无理由退换。未开封全额退,开封吃了不适应退50%。我家做长期生意的,不怕验货,就怕您不验。新粉关注领券更划算。' AS answer, '猫粮,验货,确认,退换,保障' AS tags, '猫粮验货与退换保障话术' AS source_summary, 82 AS score
  UNION ALL SELECT 'pet_food', '别家同款比你便宜20块,能少点不?', '亲,价格战我家打不起,但我能保证的是:第一,正品行货可溯源,假一赔十;第二,发货批次新鲜,保质期16个月以上;第三,售后无忧,7天无理由加质量问题包退。便宜20的那家,您看看是不是分装、是不是临期、是不是无售后。多花20买个安心,猫吃进去的东西马虎不得。今天拍我送一包冻干试吃,值这个差价,您考虑下?' AS answer, '猫粮,比价,便宜,正品,售后' AS tags, '猫粮比价销冠化解话术' AS source_summary, 92 AS score
  UNION ALL SELECT 'pet_food', '生产日期是什么时候?别是去年底的', '亲,目前发货批次生产日期是最近2个月内的,不是去年底的陈货。发货前我会拍照生产日期和生产批号给您确认,您满意了我再发,不满意可以退。猫粮保质期18个月,2个月内生产的货,到货后还有16个月以上保质期,完全新鲜。我家绝不做临期清仓,新粉关注店铺领券,回购95折,新鲜又划算。' AS answer, '猫粮,生产日期,新鲜,保质期,批次' AS tags, '猫粮生产日期承诺话术' AS source_summary, 78 AS score
  UNION ALL SELECT 'pet_food', '这款粮适合什么品种的猫?布偶能吃吗?', '亲,这款是全期全品种猫粮,布偶、英短、美短、橘猫都能吃,配方是通用的。不过布偶猫肠胃比较敏感,建议换粮时一定用7天过渡法,同时搭配益生菌。布偶属于长毛猫,这款粮添加了卵磷脂和鱼油,美毛去浮毛效果不错。如果是泌尿容易出问题的猫,建议选泌尿护理款,我店里也有。您家猫什么品种?我帮您选最合适的。' AS answer, '猫粮,品种,布偶,肠胃,美毛' AS tags, '猫粮品种适用与布偶话术' AS source_summary, 80 AS score
  UNION ALL SELECT 'pet_food', '开封了还能退吗?猫不吃怎么办?', '亲,开封了如果猫完全不吃,7天内可以退50%,因为开封后无法二次销售我承担一半损失。但建议您先拍试吃装2块钱试口性,试吃装不接受退但便宜,试错成本最低。如果大包猫不爱吃,可以试试拌冻干或猫罐头诱食,很多猫拌了就吃了。实在不吃,联系我退货,别让猫饿着。店里冻干零食搭配粮减10元,试试?' AS answer, '猫粮,退换,开封,不吃,试吃' AS tags, '猫粮开封退换与试吃话术' AS source_summary, 85 AS score
  UNION ALL SELECT 'pet_food', '猫粮怎么储存比较好?需要放冰箱吗?', '亲,猫粮不需要放冰箱,常温阴凉干燥保存就行,放冰箱反而会吸潮变质。正确储存方法:第一,原袋保存,用密封夹夹紧排出空气;第二,放在阴凉处避免阳光直射和高温;第三,别倒进塑料桶,塑料会渗油导致变质;第四,开封后45天内吃完保证新鲜。如果买的大包吃不完,分装小袋密封,放阴凉处。储存不当会导致氧化走味,猫就不吃了。' AS answer, '猫粮,储存,冰箱,密封,防潮' AS tags, '猫粮常温储存与防潮话术' AS source_summary, 80 AS score
  UNION ALL SELECT 'pet_food', '夏天配送会坏吗?是不是冷链?', '亲,猫粮是干粮水分低,常温配送不会坏,不需要冷链。夏天高温不影响猫粮品质,只要不暴晒就行,快递箱内有隔热。但罐头和湿粮夏天建议走顺丰冷链,高温运输可能变质。这款干粮常温配送完全没问题,到货后检查包装是否完好鼓包,鼓包说明变质了联系我退换。夏天建议放阴凉处储存,别放阳台暴晒。' AS answer, '猫粮,配送,夏天,冷链,干粮' AS tags, '猫粮夏天配送与干粮话术' AS source_summary, 82 AS score
  UNION ALL SELECT 'pet_food', '进口粮和国产粮到底有啥区别?你这是进口吗', '亲这款是国产粮,但配方对标进口,主蛋白是鲜鸡肉肉含量65%以上。国产粮好处是新鲜度高物流快价格实惠三分之一,进口粮海运动辄几个月到手里可能已经过半保质期。进口粮优势是品牌历史悠久品控稳定,但性价比不如国产。您要是纠结,先拍一袋试吃,狗子爱吃再回购不浪费。国产粮现在配方不输进口,别迷信进口。' AS answer, '猫粮,进口,国产,配方,性价比' AS tags, '进口粮与国产粮差异话术' AS source_summary, 88 AS score
  UNION ALL SELECT 'pet_food', '保质期是不是过半了?别发临期的', '亲,目前批次生产日期是2个月内,保质期18个月,剩余保质期16个月以上,完全没过半,更不是临期。临期粮一般指保质期剩3个月以内,我家绝不做临期清仓。发货前拍照生产日期给您确认,不满意直接退,运费我承担。建议别囤超过6个月的量,猫粮开封后45天吃完最新鲜,吃完再回购我给您留货。新粉关注领券更划算。' AS answer, '猫粮,保质期,过半,临期,新鲜' AS tags, '猫粮保质期未过半话术' AS source_summary, 85 AS score
  UNION ALL SELECT 'pet_food', '我家猫挑食得很,这款不吃能退吗?', '亲,猫主子挑食是出了名的!这款适口性不错,添加了冻干颗粒大部分猫咪都爱。但确实有挑嘴的,所以店里有30克试吃装2块钱,先试试。试吃装不接受退但便宜,试错成本最低。大包装开封后如果猫完全不吃7天内退50%。建议试吃装和冻干一起试,拌在一起猫更容易接受。挑食猫建议逐步戒掉诱食剂依赖,换天然肉香粮。' AS answer, '猫粮,挑食,试吃,退货,冻干' AS tags, '挑食猫试吃装引导话术' AS source_summary, 90 AS score
  UNION ALL SELECT 'pet_food', '每天喂多少合适?包装上写的看不懂', '亲,喂食量看猫体重和年龄,这款成猫粮建议:4公斤猫每天50到60克,5公斤60到70克,6公斤70到80克,分两餐喂。包装上的表是参考,具体看猫的体型和运动量,胖了减点瘦了加点。用手掂量,一次一小把大约30克。建议用定量勺,别凭感觉容易喂多。室内猫运动量小,宁可少喂别多喂,胖了再减就难了。有问题随时问我。' AS answer, '猫粮,喂食量,体重,定量,分餐' AS tags, '猫粮喂食量参考话术' AS source_summary, 82 AS score
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;

-- ============ 2. 宠物玩具 pet_toys (30 条) ============
INSERT INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.59', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'pet_toys' AS code, '这个逗猫棒材质安全吗?猫会咬着玩怕误食' AS question, '亲,这款逗猫棒羽毛是天然鸵鸟毛,杆子是弹性玻纤杆,无毒无害。但任何玩具都不建议让猫单独啃咬,逗猫棒是互动玩具,您陪着玩就好。如果猫喜欢咬着跑,建议搭配猫草球或猫薄荷玩具,吞食安全。互动时用画圈抽搐动作模仿小虫子,猫秒变猎手。一套搭配更划算,要不要看看?' AS answer, '逗猫棒,材质,误食,安全,互动' AS tags, '逗猫棒材质安全话术' AS source_summary, 88 AS score
  UNION ALL SELECT 'pet_toys', '狗咬胶能咬多久?我家金毛咬什么都秒碎', '亲,这款是牦牛奶酪棒,硬度很高,中型犬能咬2到4周。金毛咬合力强,但这个真不是秒碎的,因为是风干奶酪不是普通骨头。不过再硬的玩具也架不住猛犬,建议您盯着点,咬出小碎块就收走,免得吞食。店里还有耐咬等级更高的鹿角,金毛适用,凑单更划算。咬胶是消耗品,别指望咬一辈子。' AS answer, '狗咬胶,耐咬,金毛,吞食,消耗' AS tags, '狗咬胶耐咬度话术' AS source_summary, 85 AS score
  UNION ALL SELECT 'pet_toys', '逗猫棒用两次就断了,质量太差了吧', '亲,逗猫棒是易耗品,杆子有弹性极限,猛烈甩动或被猫扑折是正常的。这款采用玻纤杆,比塑料杆耐用3倍,但确实不能硬掰。如果第一次用就断,可能是运输磕碰,拍个视频我给您补发。建议逗猫时用画圈动作而不是硬拉,羽毛端别让猫咬住后硬扯,寿命更长。店里3支装减15,换着用不心疼。' AS answer, '逗猫棒,断裂,质量,易耗,玻纤' AS tags, '逗猫棒断裂化解话术' AS source_summary, 80 AS score
  UNION ALL SELECT 'pet_toys', '这个球多大?我家泰迪能玩吗', '亲,这款球直径5厘米,泰迪这个体型正合适,能叼住又能追。如果是大型犬建议拍大号7厘米,免得一口吞了。材质是天然橡胶,无毒有弹性,掉地上会弹起来,狗子追得欢。店里还有发声款,捏一下会响,狗子更疯。建议买两个换着玩,球是最容易丢的玩具,凑单减10元更划算。' AS answer, '球,泰迪,尺寸,橡胶,发声' AS tags, '球玩具尺寸匹配话术' AS source_summary, 82 AS score
  UNION ALL SELECT 'pet_toys', '我家猫对玩具根本不感兴趣,买了浪费', '亲,猫对不动的玩具没兴趣,但对会动的毫无抵抗力!这款逗猫棒加羽毛组合是激发猫狩猎本能的神器,99%的猫都追。建议抽搐式逗法模仿小虫子,猫秒变猎手。如果实在不理,7天内可退。建议搭配猫薄荷喷雾,喷一下玩具,猫直接起飞。猫不爱玩可能是无聊太久,多陪玩几天就活跃了。' AS answer, '猫玩具,没兴趣,狩猎,猫薄荷,互动' AS tags, '猫玩具激发兴趣话术' AS source_summary, 87 AS score
  UNION ALL SELECT 'pet_toys', '狗咬碎的玩具碎片会被吞下去吗?危险吗', '亲,这确实要注意!任何玩具都不能让狗单独啃到碎。这款是整块橡胶,正常咬不会碎,但如果狗牙咬穿了,碎片可能被吞。建议定期检查,发现裂痕就换新。我店这款有咬坏包换服务,3个月内咬坏拍照发我,5折换新。安全第一,别省这个钱。大型犬建议选实心橡胶款,比中空的更耐咬,不易碎。' AS answer, '狗玩具,碎裂,吞食,安全,换新' AS tags, '狗玩具碎裂吞食话术' AS source_summary, 88 AS score
  UNION ALL SELECT 'pet_toys', '毛绒玩具掉毛吗?我家狗一咬满嘴毛', '亲,这款是短毛绒不掉毛,内里是PP棉填充。但狗咬合力强的话,可能咬破掏棉花,建议有人看护下玩。如果狗喜欢撕扯,建议拍绳结玩具,耐咬不怕撕。毛绒玩具更适合叼着睡轻咬,不当撕咬玩具用。两件凑单减10元,要不要一起?选对玩具狗子才玩得久,别让狗误食棉花。' AS answer, '毛绒玩具,掉毛,棉花,绳结,撕扯' AS tags, '毛绒玩具掉毛化解话术' AS source_summary, 82 AS score
  UNION ALL SELECT 'pet_toys', '激光笔逗猫会不会伤眼睛?', '亲,激光笔确实不能直射猫眼睛,可能损伤视网膜。这款是Class 1级安全激光,功率很低,正常使用没问题。建议逗猫时打在地面或墙上,别照猫脸。其实我更推荐羽毛逗猫棒,互动感更强,猫也更满足——激光猫抓不到会挫败,逗猫棒能真实捕猎。两款价格差不多,您考虑下,猫心理健康也很重要。' AS answer, '激光笔,眼睛,安全,逗猫棒,替代' AS tags, '激光笔伤眼化解话术' AS source_summary, 85 AS score
  UNION ALL SELECT 'pet_toys', '玩具收到有塑料味,是不是有毒', '亲,新橡胶玩具出厂会有轻微味道,是材质本身的味道不是有毒。建议拆开后用温水加宠物沐浴露洗一下,通风晾半天再给猫玩,味道就散了。如果洗完还有刺鼻味,那不正常,拍照我给您退。我店这款是食品级橡胶,有检测报告,放心用。别买太便宜的玩具,材质不明对宠物健康有风险。' AS answer, '玩具,塑料味,有毒,清洗,食品级' AS tags, '玩具异味化解话术' AS source_summary, 83 AS score
  UNION ALL SELECT 'pet_toys', '幼猫两个月大能玩这个玩具吗', '亲,两个月幼猫可以玩,这款羽毛逗猫棒很轻,幼猫扑着不费力。但要注意:第一,别让幼猫啃羽毛,可能吞;第二,别让幼猫单独玩,可能缠住;第三,每次玩5到10分钟,小猫精力有限别累着。建议您陪着互动,增进感情。店里还有幼猫专属的软球玩具,更安全,凑单减5元。幼猫期多互动,长大更亲人。' AS answer, '幼猫,玩具,安全,互动,羽毛' AS tags, '幼猫玩具适用话术' AS source_summary, 86 AS score
  UNION ALL SELECT 'pet_toys', '猫爬架承重多少?我家猫12斤稳吗', '亲,这款猫爬架承重15公斤,12斤完全没问题,底座加宽设计不易翻。重点看跳板间距,12斤的猫建议间距不超过30厘米,跳着省力。如果家里有大猫,建议选立柱加粗款,更稳更耐用。猫爬架要靠墙放,别放房间中间,防止晃。店里这款有防倾倒配件,免费送,安全第一。' AS answer, '猫爬架,承重,12斤,稳定,跳板' AS tags, '猫爬架承重与稳定话术' AS source_summary, 84 AS score
  UNION ALL SELECT 'pet_toys', '飞盘适合多大狗?我家柯基能玩吗', '亲,这款飞盘直径22厘米,柯基完全能玩,叼得住扔得远。柯基腿短但运动能力强,飞盘是绝佳运动。建议在草地上玩,别在水泥地,飞盘磨损快狗爪也伤。材质是天然橡胶,软的不伤狗牙。店里还有发光飞盘,晚上玩更炫,凑单减10元。飞盘运动量大,夏天避开中午,防中暑。' AS answer, '飞盘,柯基,尺寸,橡胶,运动' AS tags, '飞盘玩具尺寸适用话术' AS source_summary, 82 AS score
  UNION ALL SELECT 'pet_toys', '这个玩具含猫薄荷吗?猫会不会上瘾', '亲,这款内置猫薄荷袋,猫闻了会兴奋打滚,但猫薄荷不上瘾,猫每天闻也不会依赖,是安全的植物。约70%的猫对猫薄荷有反应,30%无感是基因决定。如果担心,有不加猫薄荷的纯羽毛款。猫薄荷玩具一周玩2到3次就够了,别太频繁,不然猫会脱敏没反应了。店里猫薄荷喷雾单独卖,喷任何玩具都行。' AS answer, '猫薄荷,上瘾,安全,基因,脱敏' AS tags, '猫薄荷安全与上瘾话术' AS source_summary, 85 AS score
  UNION ALL SELECT 'pet_toys', '玩具上有铃铛,声音会不会吵到猫', '亲,铃铛声音很轻,猫追着玩才有声响反馈,增加趣味。正常室内铃铛声不影响猫听力,猫耳比人灵敏但铃铛音量很低。如果猫表现出害怕,把铃铛拆掉就行,这款铃铛是可拆卸的。有些猫对声音敏感,建议先观察,不适应就去铃铛。店里有无铃铛款,安静更温柔,要不要换?' AS answer, '铃铛,吵,猫听力,可拆卸,敏感' AS tags, '铃铛声音与猫听力话术' AS source_summary, 78 AS score
  UNION ALL SELECT 'pet_toys', '猫爬架占地方吗?我家40平够放吗', '亲,这款猫爬架占地40乘40厘米,高1米2,40平完全放得下,靠墙角放最省空间。如果家里实在小,建议选壁挂式猫跳板,不占地面空间,墙上装3到4块,猫也能爬。猫爬架对猫很重要,猫需要垂直空间,没有爬架猫会爬柜子抓沙发。店里壁挂款3块装减20,小户型首选,要不要看看?' AS answer, '猫爬架,占地,小户型,壁挂,垂直' AS tags, '猫爬架占地与小户型话术' AS source_summary, 80 AS score
  UNION ALL SELECT 'pet_toys', '这个绳结玩具狗会吞线吗?怕肠梗阻', '亲,绳结玩具确实有吞线风险,所以一定要选密实编织的,这款是纯棉绳紧密编织,正常咬不会散线。但狗咬散了就要收走,别让吞。建议绳结玩具在有人看护下玩,别给狗单独啃。如果是爱吞东西的狗,建议选整块橡胶玩具更安全。绳结玩具的好处是能洁牙,狗咬着磨牙,比咬胶便宜。' AS answer, '绳结,吞线,肠梗阻,安全,洁牙' AS tags, '绳结玩具吞线安全话术' AS source_summary, 85 AS score
  UNION ALL SELECT 'pet_toys', '多猫家庭买几个玩具够用?', '亲,多猫家庭建议逗猫棒至少2支,球类3到4个,猫爬架至少1个。猫会争玩具,少了会打架。逗猫棒要分开逗,一只一只来,不然猫会打架。球类多买几个散在地上,猫各玩各的。猫爬架要选多层的,猫各有地盘不打架。店里多猫套装3逗猫棒加5球减30,多猫家庭必备,要不要凑单?' AS answer, '多猫,玩具,数量,打架,地盘' AS tags, '多猫家庭玩具数量话术' AS source_summary, 83 AS score
  UNION ALL SELECT 'pet_toys', '这个球会发光吗?晚上猫能看见玩吗', '亲,这款是夜光球,吸光后在暗处会发光,猫晚上能看见自己玩。但夜光效果持续约30分钟,需要光照激活。如果想要更亮,建议拍LED发光球,电池款持续亮8小时。猫夜视能力强,普通球晚上也能看到轮廓。发光球是锦上添花,猫觉得更有趣。店里LED球和夜光球套装减15,晚上哄猫神器。' AS answer, '球,发光,夜光,LED,晚上' AS tags, '夜光球晚上玩耍话术' AS source_summary, 80 AS score
  UNION ALL SELECT 'pet_toys', '玩具耐咬吗?我家哈士奇秒拆', '亲,哈士奇是拆家王者!普通玩具确实扛不住。建议选这款牦牛奶酪棒或鹿角,硬度最高,哈士奇能咬1到2周。毛绒和绳结类就别买了,秒碎。橡胶玩具选实心款,比中空耐咬。任何玩具别让哈士奇单独啃,看着点,咬碎就收。店里耐咬专区有3款适合哈士奇,凑单减20,您要看看吗?' AS answer, '耐咬,哈士奇,拆家,鹿角,奶酪棒' AS tags, '哈士奇耐咬玩具话术' AS source_summary, 87 AS score
  UNION ALL SELECT 'pet_toys', '逗猫棒羽毛会掉吗?猫吃了没事吧', '亲,羽毛是天然鸵鸟毛,会有轻微掉毛,但猫少量吃羽毛没事,会随便便排出。建议:逗猫时别让猫长时间啃羽毛;羽毛掉多了就换新的,一支用1到2个月正常。如果担心,建议选布条或毛绒头的逗猫棒,不掉毛。这款羽毛款吸引力最强,猫最爱追。店里3支装减15,换着用,掉了也不心疼。' AS answer, '逗猫棒,羽毛,掉毛,误食,安全' AS tags, '逗猫棒羽毛掉落话术' AS source_summary, 82 AS score
  UNION ALL SELECT 'pet_toys', '这个玩具猫玩两天就不玩了,咋办', '亲,猫对新玩具有3天热度是正常的,之后不玩是因为玩具不动了。建议:第一,玩具收起来,隔几天拿出来保持新鲜感;第二,逗猫棒要主动逗,猫对会动的感兴趣;第三,猫薄荷喷雾喷一下,猫重新兴奋;第四,一次别给太多玩具,一个一个轮换。猫天性猎手,需要变化和挑战,同个玩具天天摆着猫当然腻。轮换法最有效。' AS answer, '猫玩具,不玩,新鲜感,轮换,猫薄荷' AS tags, '猫玩具保鲜与轮换话术' AS source_summary, 84 AS score
  UNION ALL SELECT 'pet_toys', '猫爬架安装麻烦吗?一个人能装吗', '亲,这款猫爬架是模块化设计,螺丝连接,一个人半小时能装好。包装内有安装图纸和工具,按步骤来不难。建议:第一,先分类零件;第二,从底座开始往上装;第三,螺丝先别拧紧,全部装完再拧紧。如果装不好可以看店铺安装视频。靠墙安装更稳,有防倾配件免费送。店里升级款免工具拼装,3分钟搞定,贵20元,您要看看吗?' AS answer, '猫爬架,安装,模块化,螺丝,工具' AS tags, '猫爬架安装话术' AS source_summary, 78 AS score
  UNION ALL SELECT 'pet_toys', '这个咬胶有添加剂吗?狗吃了安全吗', '亲,这款牦牛奶酪棒配料只有牦牛奶和少量盐,无防腐剂无色素无诱食剂。制作工艺是传统风干,奶发酵变硬,自然成型的。狗吃了完全安全,还能补钙洁牙。辨别方法:看配料表越短越干净,这款只有两样。别买配料表一长串的咬胶,添加剂多。这款一包3根,中型犬咬3周,凑单减10元。' AS answer, '咬胶,添加剂,安全,牦牛奶,洁牙' AS tags, '咬胶无添加话术' AS source_summary, 85 AS score
  UNION ALL SELECT 'pet_toys', '玩具用水洗了会掉色吗?能机洗吗', '亲,这款毛绒玩具色牢度高,手洗不掉色。建议冷水手洗,别机洗,机洗容易把填充棉搅散变形。洗完自然晾干,别烘干。橡胶玩具用温水加洗洁精洗就行,晾干后给猫玩。绳结玩具可以机洗,装洗衣袋。玩具定期清洗,猫舔咬不卫生。建议两件换洗,一件用一件洗,凑单减10元更划算。' AS answer, '玩具,水洗,掉色,机洗,清洁' AS tags, '玩具清洗与掉色话术' AS source_summary, 80 AS score
  UNION ALL SELECT 'pet_toys', '这个玩具适合几个月的猫?幼猫能玩吗', '亲,逗猫棒类玩具3个月以上的猫就能玩,但幼猫要注意别让啃羽毛。球类玩具2个月以上就能玩,选轻的软的。猫爬架建议6个月以上用,太小跳不上。咬胶类玩具6个月以上,幼猫牙没长齐别咬硬的。您家猫几个月?我帮您推荐合适的。幼猫期多互动玩具,长大亲人不怕人,性格好。' AS answer, '玩具,月龄,幼猫,适用,互动' AS tags, '玩具月龄适用话术' AS source_summary, 82 AS score
  UNION ALL SELECT 'pet_toys', '猫爬架柱子够磨爪吗?猫会抓坏沙发吗', '亲,这款猫爬架立柱缠的是天然剑麻绳,猫抓着爽,耐磨能用半年以上。猫磨爪是天性,有猫爬架抓就不会抓沙发。建议猫爬架放在猫常路过的地方,喷点猫薄荷吸引。如果猫还是抓沙发,在沙发上贴防抓贴。店里剑麻绳替换装5元一根,柱子抓散了自己缠,不用换整个爬架,省钱。' AS answer, '猫爬架,磨爪,剑麻,沙发,替换' AS tags, '猫爬架磨爪与防沙发话术' AS source_summary, 84 AS score
  UNION ALL SELECT 'pet_toys', '这个球太轻了,狗一咬就弹飞找不到', '亲,橡胶球确实轻,建议选这款带绳的球,扔出去能拉回来不会丢。或者选重量款,里面加了配重,扔得远不飘。小球容易钻沙发底,建议买大一号或选能滚出来的光滑款。如果家里球经常丢,建议买一袋10个装,丢了不心疼。店里10球装减20,够狗玩半年,要不要凑单?' AS answer, '球,轻,丢失,带绳,配重' AS tags, '球玩具丢失化解话术' AS source_summary, 78 AS score
  UNION ALL SELECT 'pet_toys', '玩具包装里有清单吗?配件全吗', '亲,包装内有玩具清单和说明书,发货前我会核对配件齐全再发。如果收到缺件,48小时内联系我补发,运费我承担。这款逗猫棒套装含杆子1支羽毛头2个铃铛球1个,配件可替换。替换头单独卖5元2个,羽毛掉了换新的就行,杆子不用换。店里替换头10个装减10元,囤着用。' AS answer, '玩具,包装,清单,配件,替换' AS tags, '玩具配件清单话术' AS source_summary, 75 AS score
  UNION ALL SELECT 'pet_toys', '这个玩具狗玩腻了怎么办?能退吗', '亲,狗玩腻是正常的,狗需要新鲜感。建议:第一,玩具轮换,隔几天换一个;第二,互动玩比让狗自己玩更有趣;第三,咬胶类沾点肉汤,重新吸引。如果狗完全不玩,7天内未损坏可退。玩具是消耗品,玩坏了正常,别期望一个玩具玩一年。建议多买几种换着用,凑单更划算。' AS answer, '狗玩具,玩腻,轮换,退货,消耗' AS tags, '狗玩具玩腻化解话术' AS source_summary, 80 AS score
  UNION ALL SELECT 'pet_toys', '猫爬架稳固吗?猫跳上去会翻吗', '亲,这款猫爬架底座加宽加厚,承重15公斤,猫跳上去稳稳的不翻。关键是要靠墙放,别放房间中间,靠墙后重心稳。建议安装时用防倾倒配件固定在墙上,有小孩或大猫的必须固定。猫爬架跳板间距30厘米以内,猫跳着轻松不晃。如果猫第一次用不敢跳,用零食引导从底层开始,慢慢往上。店里防倾配件免费送,安全第一。' AS answer, '猫爬架,稳固,翻倒,防倾,靠墙' AS tags, '猫爬架稳固与防倾话术' AS source_summary, 83 AS score
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;

-- ============ 3. 宠物服饰 pet_clothes (30 条) ============
INSERT INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.59', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'pet_clothes' AS code, '我家泰迪5斤穿多大码?' AS question, '亲,泰迪5斤属于小型犬,建议拍S码胸围32到36厘米背长24厘米。但每只狗体型不同,建议量一下胸围前腿后方一圈和背长脖子到尾巴根,按尺码表选。卡在两个码之间选大一码,穿着不勒。尺码不合适7天内可换,运费各付一程。店里还有同款母女装,要不要看看?量准尺寸最重要,别凭体重猜。' AS answer, '狗衣服,泰迪,尺码,胸围,背长' AS tags, '泰迪衣服尺码测量话术' AS source_summary, 88 AS score
  UNION ALL SELECT 'pet_clothes', '猫衣服穿上一动不动,是不是不舒服', '亲,猫第一次穿衣服都会石化,是正常的应激反应,不是不舒服。建议先穿5分钟适应,每天延长一点,一周后就习惯了。这款是四面弹面料,不勒不紧,猫适应后能正常走路跑跳。如果穿了一周还是不动,可能是尺寸太紧,拍个视频我帮您判断。建议先从背心款开始适应,比四脚款好接受。' AS answer, '猫衣服,应激,不动,适应,背心' AS tags, '猫衣服应激化解话术' AS source_summary, 85 AS score
  UNION ALL SELECT 'pet_clothes', '衣服材质扎不扎人?狗穿着会不会痒', '亲,这款是摇粒绒内里加纯棉外层,亲肤不扎,人摸着都软。狗毛厚,衣服穿在最外层,不会直接接触皮肤,不会痒。如果您家狗是短毛比如法斗灵缇,建议选纯棉款,更柔软。店里还有带脖圈款的防寒服,短毛狗专属,凑单减15。短毛狗皮肤敏感,别穿粗糙面料,会磨红。' AS answer, '狗衣服,材质,扎人,短毛,亲肤' AS tags, '衣服材质亲肤话术' AS source_summary, 83 AS score
  UNION ALL SELECT 'pet_clothes', '这个棉衣零下能穿吗?我家在东北', '亲,这款是加厚摇粒绒,适合0到10度。东北零下的话建议拍极寒款,内层是羽绒棉,外层防风,能扛零下15度。普通棉衣零下扛不住,狗出门还是会冷。东北客户建议拍极寒款加四脚鞋,脚掌防冻裂。两件套今天有满199减40,很划算。别让狗零下20度穿薄棉衣出门,会冻伤的。' AS answer, '棉衣,零下,东北,极寒,防风' AS tags, '棉衣零下适用话术' AS source_summary, 87 AS score
  UNION ALL SELECT 'pet_clothes', '夏天狗穿衣服不热吗', '亲,夏天穿衣服主要是防晒和防虫,不是保暖。这款是冰丝凉感面料,穿上比裸奔还凉快,降低2到3度,还能防蚊虫叮咬防草籽划伤。短毛狗比如法斗灵缇夏天户外强烈建议穿,防晒防皮肤癌。如果纯室内养可以不穿。店里还有冷却背心,湿水后穿更凉,要不要看看?夏天遛狗避开中午高温。' AS answer, '狗衣服,夏天,热,防晒,冰丝' AS tags, '夏装凉感防晒话术' AS source_summary, 84 AS score
  UNION ALL SELECT 'pet_clothes', '衣服洗了会变形缩水吗', '亲,这款是预缩水处理过的纯棉,正常机洗冷水加轻柔模式不会变形缩水。建议装洗衣袋,避免和硬物摩擦。别烘干,自然晾干即可。如果洗后轻微变形,蒸汽熨斗一熨就恢复。色牢度高,不掉色不串色,放心洗。建议买两件换洗,一件穿一件洗,凑单减10元更划算。别用漂白剂,会破坏面料。' AS answer, '衣服,洗,变形,缩水,色牢度' AS tags, '衣服洗涤不变形话术' AS source_summary, 80 AS score
  UNION ALL SELECT 'pet_clothes', '四脚衣服太难穿了,狗一直挣扎', '亲,四脚衣确实比背心难穿,有技巧:第一,先套前腿再套头最后套后腿;第二,穿的时候给点零食分散注意力;第三,每天穿一次,一周就习惯了。如果狗实在抗拒,建议改拍两腿背心款,前腿套一下就完事,穿着率更高。店里背心款今天有第二件半价,要不要换?别硬穿,狗会讨厌衣服。' AS answer, '四脚衣,难穿,挣扎,背心,技巧' AS tags, '四脚衣穿法技巧话术' AS source_summary, 82 AS score
  UNION ALL SELECT 'pet_clothes', '我家猫18斤,有加大码吗', '亲,18斤是胖猫!我店有XXL码胸围48到52厘米,胖猫专属,加宽版型不勒肚子。建议量一下胸围确认,18斤橘猫或缅因通常穿XXL。如果更大,支持定制,加20元按您尺寸做。胖猫穿衣服要选弹性款,别勒着影响呼吸。店里胖猫款有满2件减20,建议囤换洗。胖猫也要美美的!' AS answer, '猫衣服,胖猫,加大码,定制,弹性' AS tags, '胖猫加大码话术' AS source_summary, 86 AS score
  UNION ALL SELECT 'pet_clothes', '雨衣真的防水吗?下大雨能穿吗', '亲,这款是防水面料加热压工艺,中雨完全没问题,大雨短时间也扛得住。重点是接缝做了压胶处理,不渗水。但任何雨衣都不能长时间泡水,大雨建议速去速回。下完雨脱下来甩干晾着就行。店里还有配套雨鞋,四脚防滑,凑单减10元,整套更实用。雨天遛狗必备,别让狗淋湿感冒。' AS answer, '雨衣,防水,大雨,压胶,雨鞋' AS tags, '雨衣防水话术' AS source_summary, 82 AS score
  UNION ALL SELECT 'pet_clothes', '项圈会勒脖子吗?狗戴着不舒服吧', '亲,这款是软垫项圈,内层有海绵填充,不勒脖子不磨毛。关键是尺寸要对——您能塞进两根手指就合适,太松会挣脱太紧会勒。建议选快拆扣款,紧急情况一按就开,更安全。店里还有胸背带款,受力分散到胸前,小型犬更推荐,不伤气管。两件套有折扣,胸背带比项圈对小型犬更友好。' AS answer, '项圈,勒脖子,软垫,胸背带,快拆' AS tags, '项圈不勒与胸背带话术' AS source_summary, 84 AS score
  UNION ALL SELECT 'pet_clothes', '牵引绳多长?适合在小区遛狗吗', '亲,这款牵引绳1.2米,适合小区遛狗,控制力强狗不会跑太远。如果是公园开阔地,建议拍可伸缩款,3到5米,狗能跑开又可控。1.2米是标准训练长度,适合教狗随行。建议别用太长的绳,小区有车有狗,安全第一。店里伸缩绳减15元,要不要凑单?牵引绳是遛狗必备,别图便宜买劣质的,断了就出事。' AS answer, '牵引绳,长度,小区,伸缩,安全' AS tags, '牵引绳长度适用话术' AS source_summary, 82 AS score
  UNION ALL SELECT 'pet_clothes', '狗狗鞋子防滑吗?穿了会不会摔', '亲,这款鞋底是防滑橡胶,有凹凸纹路,防滑效果好。狗第一次穿鞋会奇怪走路不稳,建议在家穿半小时适应,出门就正常了。鞋子主要防烫防冻防割伤,夏天柏油路60度会烫伤脚垫,冬天零下会冻裂,穿了鞋就没事。建议选魔术贴款,穿脱方便不易掉。四脚鞋套装减20,要不要看看?' AS answer, '狗鞋,防滑,烫伤,冻裂,适应' AS tags, '狗鞋防滑与适应话术' AS source_summary, 83 AS score
  UNION ALL SELECT 'pet_clothes', '衣服有反光条吗?晚上遛狗安全吗', '亲,这款衣服和牵引绳都有反光条,车灯一照就亮,晚上遛狗更安全。建议晚上遛狗必穿带反光的衣服或项圈,司机能看到。店里还有LED发光项圈,闪烁模式,更醒目,凑单减15。晚上遛狗别走机动车道,尽量走人行道。反光装备是遛狗安全标配,别省这个钱。' AS answer, '衣服,反光条,晚上,遛狗,安全' AS tags, '反光条遛狗安全话术' AS source_summary, 80 AS score
  UNION ALL SELECT 'pet_clothes', '猫能穿衣服吗?猫会不会抗拒', '亲,猫比狗更抗拒穿衣服,但短时间穿是可以的。建议:第一,从背心款开始,比四脚款好接受;第二,先穿5分钟,慢慢延长;第三,穿的时候给零食奖励。猫衣服主要用途是防掉毛和保暖,短毛猫冬天可以穿。如果猫完全不接受别硬穿,会应激。无毛猫冬天必须穿,没毛会冷。' AS answer, '猫衣服,抗拒,适应,背心,无毛猫' AS tags, '猫穿衣服适应话术' AS source_summary, 84 AS score
  UNION ALL SELECT 'pet_clothes', '衣服拉链会卡到狗毛吗', '亲,这款拉链内侧有挡布,不会卡毛。建议拉的时候用手按住挡布,慢慢拉。如果狗毛很长,建议选魔术贴款,没有拉链,穿脱更方便不卡毛。长毛狗如金毛萨摩耶,拉链款容易卡毛,魔术贴款更友好。店里魔术贴款减10元,长毛狗首选。别买劣质拉链的,卡毛一次狗就讨厌穿衣服了。' AS answer, '衣服,拉链,卡毛,魔术贴,长毛' AS tags, '拉链卡毛化解话术' AS source_summary, 80 AS score
  UNION ALL SELECT 'pet_clothes', '这件衣服适合长毛狗还是短毛狗', '亲,这款适合短毛狗,纯棉面料柔软,短毛狗穿着不磨皮肤。长毛狗建议选网眼透气款,长毛不闷不容易打结。长毛狗穿衣服容易捂热和毛打结,建议只在外出时穿,回家脱掉梳理。短毛狗如法斗吉娃娃冬天必须穿,没毛会冷。您家狗什么品种?我帮您推荐最合适的款式和面料。' AS answer, '衣服,长毛,短毛,面料,透气' AS tags, '衣服长短毛适用话术' AS source_summary, 82 AS score
  UNION ALL SELECT 'pet_clothes', '项圈材质是什么?会过敏吗', '亲,这款项圈是尼龙编织,内衬软垫,低敏材质,大部分狗不会过敏。如果狗是高度敏感体质,建议选纯棉或真皮款,更亲肤。金属扣是不锈钢的,不生锈不过敏。别买劣质塑料扣的,容易断还可能过敏。新项圈戴第一天观察有没有红印,有的话可能过敏,换材质。店里真皮款减20,敏感狗首选。' AS answer, '项圈,材质,过敏,尼龙,真皮' AS tags, '项圈材质过敏话术' AS source_summary, 83 AS score
  UNION ALL SELECT 'pet_clothes', '牵引绳手柄舒服吗?遛久了手疼吗', '亲,这款手柄有海绵缓冲套,握着舒服,遛久了不勒手。如果狗力气大,建议选双手柄款,两只手握更省力。还有腰挎款,绑腰上解放双手,跑步遛狗首选。建议别用太细的绳,狗一冲手就勒红。店里双手柄款减15,大狗必备。牵引绳质量关系到遛狗安全,别买几块钱的,断了狗跑丢就麻烦了。' AS answer, '牵引绳,手柄,舒服,双手柄,腰挎' AS tags, '牵引绳手柄舒适话术' AS source_summary, 78 AS score
  UNION ALL SELECT 'pet_clothes', '衣服厚度怎么样?秋天穿够吗', '亲,这款是摇粒绒加厚款,厚度适中,0到15度穿正合适,秋天完全够。如果是深秋初冬0度以下,建议拍羽绒款更厚。这款适合春秋和初冬,南方冬天也够。北方冬天室内有暖气,穿这个正好。建议看当地温度选厚度,别穿太厚狗会热,太薄会冷。店里薄款和厚款都有,告诉我您那边温度,我帮您推荐。' AS answer, '衣服,厚度,秋天,摇粒绒,温度' AS tags, '衣服厚度与季节话术' AS source_summary, 80 AS score
  UNION ALL SELECT 'pet_clothes', '狗狗鞋子尺码怎么量?怎么选', '亲,量狗脚的方法:让狗站在白纸上,画脚的轮廓,量最宽处和最长处,按尺码表选。建议选大一码,留点空间。或者把狗脚踩湿,按在纸上量水印。前脚和后脚大小可能不同,建议都量。穿鞋要紧但不勒,能塞进一根手指刚好。第一次穿在家适应半小时,别直接出门,狗会不习惯。' AS answer, '狗鞋,尺码,测量,脚长,脚宽' AS tags, '狗鞋尺码测量话术' AS source_summary, 82 AS score
  UNION ALL SELECT 'pet_clothes', '有防丢牌吗?项圈上能挂吗', '亲,这款项圈有专属挂环,可以挂防丢牌和铃铛。防丢牌建议刻上狗的名字和您的电话,丢了别人能联系您。店里定制防丢牌15元,不锈钢材质不掉色,刻字免费。建议项圈加防丢牌加芯片三重保障,狗跑丢也不怕。防丢牌是遛狗必备,别省这个钱,狗跑丢了找不回来才后悔。' AS answer, '防丢牌,项圈,挂环,定制,芯片' AS tags, '防丢牌与项圈话术' AS source_summary, 84 AS score
  UNION ALL SELECT 'pet_clothes', '衣服弹性怎么样?狗胖了能穿吗', '亲,这款是四面弹面料,弹性很大,狗胖一点也能穿。但别超过尺码范围太多,太紧会影响呼吸。建议胖狗选大一码,或者拍弹性更好的弹力款。如果狗正在减肥,买合适尺码,瘦了再换。别买太紧的,狗不舒服会抗拒穿。店里加宽胖狗款减15,胖狗专属,要不要看看?' AS answer, '衣服,弹性,胖狗,四面弹,加宽' AS tags, '衣服弹性与胖狗话术' AS source_summary, 80 AS score
  UNION ALL SELECT 'pet_clothes', '雨衣透气吗?狗穿着会不会闷', '亲,这款雨衣是防水透气面料,内层有网眼透气,不会闷。但任何雨衣都不如不穿透气,建议雨停了就脱。如果长时间穿,狗会捂出湿疹。建议选轻薄的折叠款,随身带着下雨穿,晴了脱。店里还有带透气孔的款,更通风,凑单减10元。雨天遛狗穿脱方便很重要,别买太厚重的。' AS answer, '雨衣,透气,闷,网眼,轻薄' AS tags, '雨衣透气话术' AS source_summary, 78 AS score
  UNION ALL SELECT 'pet_clothes', '项圈戴多紧合适?会不会勒', '亲,项圈松紧度标准是:能塞进两根手指就合适。太松狗会挣脱,太紧会勒影响呼吸。建议:第一,定期检查松紧,狗胖了瘦了都要调;第二,长毛狗把毛拨开再调;第三,选快拆扣紧急时一按就开。幼犬生长快,项圈要经常调松,别勒着。店里可调节款减10元,调节范围大,从小戴到大。' AS answer, '项圈,松紧,勒,手指,调节' AS tags, '项圈松紧标准话术' AS source_summary, 82 AS score
  UNION ALL SELECT 'pet_clothes', '牵引绳承重多少?大型犬能用吗', '亲,这款牵引绳承重80公斤,大型犬如金毛拉布拉多完全能用。如果是力气很大的狗如阿拉斯加,建议拍加厚款,承重150公斤。牵引绳要看缝合密度和扣环材质,这款是双重缝合加不锈钢扣,拉不断。建议大型犬用双手柄加厚款,控制力更强。店里加厚款减20元,大狗必备,别用细绳遛大狗,危险。' AS answer, '牵引绳,承重,大型犬,缝合,扣环' AS tags, '牵引绳承重话术' AS source_summary, 85 AS score
  UNION ALL SELECT 'pet_clothes', '衣服掉色吗?和别的衣服一起洗会串色吗', '亲,这款色牢度4级以上,正常洗涤不掉色不串色。但第一次洗建议单独洗,深色衣服可能轻微浮色。建议:第一,冷水洗别用热水;第二,翻过来洗减少摩擦;第三,别用漂白剂。如果还是有色落,联系我退换。深色衣服和浅色分开洗最保险。店里多色款减10元,选颜色时备注就行。' AS answer, '衣服,掉色,串色,色牢度,洗涤' AS tags, '衣服掉色串色话术' AS source_summary, 80 AS score
  UNION ALL SELECT 'pet_clothes', '这件适合短鼻犬吗?法斗能穿吗', '亲,法斗是短鼻犬,呼吸本来就弱,穿衣服别太紧勒胸口。这款是宽松版型,法斗能穿。建议选前开扣款,不勒脖子,短鼻犬更舒服。别穿高领款,会压迫气道。法斗夏天怕热,穿冰丝凉感款,别穿厚款。短鼻犬冬天也怕冷,穿薄棉就好。店里有短鼻犬专属款,前开扣宽松,减15元,要不要看看?' AS answer, '衣服,短鼻犬,法斗,宽松,前开扣' AS tags, '短鼻犬衣服适用话术' AS source_summary, 85 AS score
  UNION ALL SELECT 'pet_clothes', '衣服洗涤说明有吗?怎么洗最好', '亲,每件衣服内侧都有洗涤标,建议按标洗。通用方法:第一,冷水机洗轻柔模式;第二,装洗衣袋防变形;第三,中性洗涤剂别用漂白;第四,自然晾干别烘干。如果是摇粒绒,别和棉的一起洗会粘毛。建议两件换洗,一件穿一件洗。正确洗护衣服寿命长,别随手扔洗衣机,容易变形。' AS answer, '衣服,洗涤,说明,洗衣袋,晾干' AS tags, '衣服洗涤说明话术' AS source_summary, 78 AS score
  UNION ALL SELECT 'pet_clothes', '这套带胸背带吗?还是只有衣服', '亲,这款是衣服款,不含胸背带。如果您需要胸背带,建议拍套装款,衣服加胸背带一套,出门不用再套项圈,方便。胸背带比项圈好,受力分散不伤气管,小型犬首选。套装比单买便宜20元,更划算。您家狗多大?我帮您选合适尺码。胸背带要量胸围,和衣服尺码可能不同,别搞混。' AS answer, '胸背带,衣服,套装,项圈,胸围' AS tags, '衣服与胸背带套装话术' AS source_summary, 82 AS score
  UNION ALL SELECT 'pet_clothes', '这个尺码表我看不懂,能帮我选吗', '亲,尺码表看胸围和背长就行。胸围是前腿后方一圈最宽处,背长是脖子根到尾巴根。您量好后告诉我,我帮您选。如果卡在两个码之间选大一码。不同品牌尺码可能不同,别按之前的尺码买,每件都要量。建议用软尺量,别用直尺,不准。量不准的话发我狗的照片,我凭经验估个码,不合适7天可换。' AS answer, '尺码表,胸围,背长,选码,软尺' AS tags, '尺码表帮选话术' AS source_summary, 80 AS score
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;

-- ============ 4. 宠物用具 pet_supplies_misc (30 条) ============
INSERT INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.59', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'pet_supplies_misc' AS code, '猫砂盆多大?我家猫15斤装得下吗' AS question, '亲,这款是加大型52乘40乘18厘米,15斤胖猫完全装得下,我家16斤橘猫在用同款。重点是边沿高15厘米,猫刨砂不飞出来。如果是幼猫或老猫,建议选低边款8厘米,进出方便。店里还有全封闭款,防臭防带砂,凑单减30,胖猫家庭强推。' AS answer, '猫砂盆,尺寸,胖猫,封闭,边沿' AS tags, '猫砂盆尺寸与胖猫话术' AS source_summary, 88 AS score
  UNION ALL SELECT 'pet_supplies_misc', '自动喂食器会卡粮吗?我出差7天担心', '亲,这款是斜坡出粮设计,不易卡粮,适配4到16毫米颗粒。但任何机器都有卡粮风险,建议您:第一,出差前先试运行3天;第二,用圆形颗粒粮,不规则粮易卡;第三,备用一碗水一碗粮,以防万一。7天出差建议搭配自动饮水器,店里套装备减50,出差无忧。别完全依赖机器,要有备用方案。' AS answer, '喂食器,卡粮,出差,备用,套装' AS tags, '自动喂食器卡粮话术' AS source_summary, 86 AS score
  UNION ALL SELECT 'pet_supplies_misc', '饮水器漏水吗?放客厅怕淹了地板', '亲,这款是真空负压原理,只要不漏气就不漏水,正常使用不会淹地板。但要注意:第一,水位别超过max线;第二,滤芯要定期换,堵塞会导致出水异常;第三,别让猫扒拉电源。我家用了半年没漏过。如果您实在担心,建议放卫生间或阳台,或者拍带托盘款,双保险。' AS answer, '饮水器,漏水,真空,托盘,滤芯' AS tags, '饮水器防漏话术' AS source_summary, 84 AS score
  UNION ALL SELECT 'pet_supplies_misc', '猫砂粉尘大吗?我和猫都怕呛', '亲,这款是豆腐猫砂,粉尘极低,几乎零粉尘,比膨润土好太多。我和猫都是过敏性鼻炎,换豆腐砂后再没打喷嚏。而且豆腐砂可冲马桶,清理方便。如果猫不接受豆腐砂,店里还有混合砂,豆腐加膨润土,结团更好,粉尘也低。两包起拍减10元,囤着用。粉尘大的猫砂伤猫呼吸道,别贪便宜。' AS answer, '猫砂,粉尘,豆腐,过敏,冲马桶' AS tags, '猫砂零粉尘话术' AS source_summary, 87 AS score
  UNION ALL SELECT 'pet_supplies_misc', '猫抓板不耐抓吧?几天就碎了', '亲,这款是密实瓦楞纸,比普通款耐用3倍,中型猫能抓2到3个月。任何猫抓板都是易耗品,猫抓是天性,磨损正常。建议您:第一,放猫常路过的地方;第二,喷点猫薄荷吸引;第三,配猫抓柱,垂直抓更爽。店里猫抓板3件套减20,换着用不腻,猫也不抓沙发了。' AS answer, '猫抓板,耐抓,瓦楞纸,猫薄荷,易耗' AS tags, '猫抓板耐用话术' AS source_summary, 82 AS score
  UNION ALL SELECT 'pet_supplies_misc', '航空箱能带上飞机吗?尺寸符合吗', '亲,这款是IATA标准航空箱,符合大部分航司托运要求。但每家航司尺寸规定略有差异,建议出行前先咨询航司。重点是:第一,门必须是金属栅栏,塑料门不让上;第二,箱体有活体动物标识;第三,水壶食盆齐全。我店这款都满足。短途出行建议拍软包款,轻便好拎,凑单减20。' AS answer, '航空箱,飞机,托运,IATA,尺寸' AS tags, '航空箱航司标准话术' AS source_summary, 88 AS score
  UNION ALL SELECT 'pet_supplies_misc', '指甲剪会剪到血线吗?我怕剪出血', '亲,新手确实容易剪到血线,建议您:第一,对着光看,粉色部分是血线,只剪白色尖尖;第二,一次剪1到2毫米,别贪多;第三,用带限位款,自动卡住剪不深。如果实在不敢剪,建议拍电动磨甲器,磨不伤血线,猫狗都能用。两款凑单减15,新手更推荐磨甲器。剪指甲别急,猫挣扎就停下来安抚。' AS answer, '指甲剪,血线,出血,磨甲器,限位' AS tags, '指甲剪血线话术' AS source_summary, 86 AS score
  UNION ALL SELECT 'pet_supplies_misc', '猫砂结团差,铲起来碎一地', '亲,豆腐砂结团确实不如膨润土紧实,但好冲马桶。如果想要强结团,建议拍混合砂,70%膨润土加30%豆腐,结团硬不碎,还能部分冲马桶。或者用沸石猫砂,结团超强无粉尘。铲砂手法也有讲究:等30秒让砂吸透再铲,别急着铲,就不碎了。店里混合砂减10元,结团党首选。' AS answer, '猫砂,结团,碎,混合砂,铲砂' AS tags, '猫砂结团差话术' AS source_summary, 83 AS score
  UNION ALL SELECT 'pet_supplies_misc', '喂食器断电了猫怎么办,会不会饿一天', '亲,这款有备用电池仓,4节5号电池,断电自动切换,能撑2到3天。还有手动出粮按钮,断电也能手动喂。建议您:第一,装电池做备用;第二,出差前满电满粮;第三,配一个传统粮碗做双保险。我店喂食器加饮水器套装备用电池都送,出差更安心。别完全信任电子产品,备用方案必须有。' AS answer, '喂食器,断电,电池,备用,双保险' AS tags, '喂食器断电话术' AS source_summary, 85 AS score
  UNION ALL SELECT 'pet_supplies_misc', '猫砂盆味道太大,屋里都臭', '亲,敞口盆确实容易散味,建议您:第一,选全封闭款,带顶盖加过滤网,味道锁住;第二,每天铲1到2次;第三,猫砂铺5厘米以上,太薄盖不住味;第四,用豆腐砂加小苏打除味粉。我店全封闭盆加除味粉套装减30,从根本上解决臭味。如果猫不用封闭盆,有半封闭顶入款,过渡更友好。' AS answer, '猫砂盆,臭味,封闭,除味,铲砂' AS tags, '猫砂盆异味话术' AS source_summary, 84 AS score
  UNION ALL SELECT 'pet_supplies_misc', '食盆防滑吗?猫吃饭老推着跑', '亲,这款食盆底部有硅胶防滑垫,猫吃饭推不动。建议选陶瓷或不锈钢款,重量够,比塑料的稳。塑料盆太轻容易滑动,而且容易留划痕滋生细菌。陶瓷盆重稳好清洗,但易碎别放高处。不锈钢盆轻便耐用不碎,最推荐。店里陶瓷加不锈钢双碗款减15元,水和粮分开,要不要看看?' AS answer, '食盆,防滑,陶瓷,不锈钢,塑料' AS tags, '食盆防滑话术' AS source_summary, 82 AS score
  UNION ALL SELECT 'pet_supplies_misc', '猫笼子多大合适?我家猫8斤', '亲,8斤的猫建议笼子至少60乘40乘50厘米,猫能站起来转身。如果长期笼养,建议80厘米以上,配吊床和猫砂盆。但猫不建议长期笼养,会影响心理。笼子适合隔离养病或临时关。如果是幼猫隔离,40厘米够了。店里折叠笼减30元,不用时折叠收纳,不占地。您买笼子什么用途?我帮您选合适尺寸。' AS answer, '猫笼,尺寸,8斤,折叠,笼养' AS tags, '猫笼尺寸话术' AS source_summary, 84 AS score
  UNION ALL SELECT 'pet_supplies_misc', '航空箱有轮子吗?方便携带吗', '亲,这款航空箱不带轮子,因为航司规定托运箱不能有轮子。如果需要轮子,建议拍宠物推车或带轮航空箱,地面推方便,但不能上飞机。短途出行建议选软包款,有背带,拎着轻便。长途自驾选硬壳箱,更安全。店里软包减20,日常带猫去医院最方便。您什么用途?我帮您推荐合适的。' AS answer, '航空箱,轮子,软包,托运,携带' AS tags, '航空箱轮子话术' AS source_summary, 80 AS score
  UNION ALL SELECT 'pet_supplies_misc', '食盆可以水洗吗?放洗碗机吗', '亲,这款不锈钢和陶瓷食盆都可以水洗,放洗碗机没问题。建议每天洗一次,食盆不洗会滋生细菌,猫吃了容易黑下巴。塑料盆不建议放洗碗机,高温会变形。建议选不锈钢盆,最耐用最易清洗,不掉色不藏菌。陶瓷盆好看但重,手洗更安全。店里不锈钢双碗减10元,猫狗通用,要不要凑单?' AS answer, '食盆,水洗,洗碗机,不锈钢,陶瓷' AS tags, '食盆水洗话术' AS source_summary, 80 AS score
  UNION ALL SELECT 'pet_supplies_misc', '笼子有几个门?方便打扫吗', '亲,这款笼子有三个门,正面大门加顶部开门加侧面小门,打扫和抓猫都方便。顶部开门最好用,把猫从上面放进去不费劲。底部有抽屉式托盘,拉出来冲洗就行,很方便。建议铺尿垫在托盘上,脏了换尿垫,不用每次洗托盘。店里笼子配件套装减20,含吊床水壶食盆,要不要一起?' AS answer, '笼子,门,打扫,托盘,尿垫' AS tags, '笼子门与打扫话术' AS source_summary, 82 AS score
  UNION ALL SELECT 'pet_supplies_misc', '航空箱门锁牢吗?猫会不会拱开', '亲,这款航空箱是双重门锁,旋转锁加卡扣,猫拱不开。而且门是金属栅栏,猫咬不烂。建议出行前检查门锁是否扣紧,用扎带再固定一道更保险。如果猫特别爱越狱,建议选带密码锁款,更安全。店里航空箱配件含扎带和标识贴,免费送,出行必备。别买门锁松的,猫跑出去就麻烦了。' AS answer, '航空箱,门锁,越狱,扎带,安全' AS tags, '航空箱门锁话术' AS source_summary, 84 AS score
  UNION ALL SELECT 'pet_supplies_misc', '猫砂盆半封闭还是全封闭好?', '亲,各有优缺点。全封闭防臭防带砂好,但有些猫不接受,觉得憋屈。半封闭防带砂一般,但猫容易接受。建议:第一,幼猫和老猫选半封闭,进出方便;第二,成年猫选全封闭,防臭好;第三,多猫家庭选大号全封闭。如果猫不接受全封闭,有顶入式款,从上面进去,猫觉得不憋屈,防带砂也好。' AS answer, '猫砂盆,封闭,半封闭,顶入,防臭' AS tags, '猫砂盆封闭选择话术' AS source_summary, 85 AS score
  UNION ALL SELECT 'pet_supplies_misc', '食盆高度合适吗?猫吃饭要弯腰吗', '亲,这款食盆高度8厘米,适合成年猫,不用弯腰太多。如果是大型犬,建议选高架食盆,高度可调,狗不用低头吃,对颈椎好。小型犬和猫用低盆就行。高架食盆适合老年犬和大型犬,减少颈椎和关节压力。建议食盆高度到宠物胸口位置最合适。店里高架款减20,大狗必备,要不要看看?' AS answer, '食盆,高度,弯腰,高架,颈椎' AS tags, '食盆高度话术' AS source_summary, 80 AS score
  UNION ALL SELECT 'pet_supplies_misc', '笼子底网会卡脚吗?猫脚会不会疼', '亲,这款笼子底网间距1.2厘米,猫脚不会卡。但幼猫脚小,建议铺垫板,防止卡脚。底网的好处是便便掉下去,猫不踩到。建议底网下放尿垫,脏了换。如果猫不适应底网,可以铺一层软垫,但要定期清洗。店里笼子垫板减10元,幼猫和老猫必备,脚不疼更舒服。' AS answer, '笼子,底网,卡脚,垫板,幼猫' AS tags, '笼子底网话术' AS source_summary, 82 AS score
  UNION ALL SELECT 'pet_supplies_misc', '航空箱透气吗?猫在里面会闷吗', '亲,这款航空箱四周有通风栅栏,透气性好,猫不会闷。但夏天别放太阳下暴晒,箱内温度会很高。建议出行选早晚凉快时段,箱内放冰垫降温。冬天出行注意保暖,箱内垫毛毯。航空箱透气孔是IATA标准要求的,保证空气流通。店里冰垫减10元,夏天出行必备,别让猫中暑。' AS answer, '航空箱,透气,闷,通风,冰垫' AS tags, '航空箱透气话术' AS source_summary, 80 AS score
  UNION ALL SELECT 'pet_supplies_misc', '自动喂食器容量多大?够几天的', '亲,这款喂食器容量4升,约2公斤粮,中型犬够3到4天,猫够10到15天。建议别装太满,保持新鲜。出差前满粮满电,设定定时定量。建议搭配监控摄像头,远程看宠物吃饭情况。店里喂食器加摄像头套装备减50,出差也能看着毛孩子。容量选择看宠物大小和出差天数,别买太小。' AS answer, '喂食器,容量,天数,出差,监控' AS tags, '喂食器容量话术' AS source_summary, 83 AS score
  UNION ALL SELECT 'pet_supplies_misc', '饮水机过滤要换滤芯吗?多久换', '亲,这款饮水机有滤芯,建议2到4周换一次,看水质和猫毛量。滤芯活性炭加离子交换树脂,过滤杂质和异味。不换滤芯水质变差,猫不爱喝容易尿闭。建议多买几个滤芯备用,店里5个装减20元,够用半年。饮水机要每周清洗一次,猫毛和滑腻物会影响水质。多喝水对猫肾脏好,别省滤芯钱。' AS answer, '饮水机,滤芯,更换,清洗,水质' AS tags, '饮水机滤芯话术' AS source_summary, 85 AS score
  UNION ALL SELECT 'pet_supplies_misc', '猫砂盆多大合适?两只猫用', '亲,两只猫建议至少两个猫砂盆,或者一个大号猫砂盆加一个小号。猫砂盆数量原则是猫数量加一,两只猫三个盆最好。猫有地盘意识,共用一个盆可能不拉。大号盆建议60厘米以上,猫转身不挤。如果空间有限,选双层猫砂盆,上下两个,省空间。店里双猫套装减30,两个大盆,要不要看看?' AS answer, '猫砂盆,多猫,数量,地盘,双层' AS tags, '多猫猫砂盆话术' AS source_summary, 84 AS score
  UNION ALL SELECT 'pet_supplies_misc', '食碗是不锈钢的吗?会不会生锈', '亲,这款是304食品级不锈钢,不生锈不腐蚀,人用级别安全。建议别买201不锈钢,会生锈还可能含重金属。辨别方法:304有钢印,201没有;304用磁铁吸不住,201能吸住。不锈钢碗比塑料和陶瓷都耐用,掉地上不碎,最推荐。店里304双碗减15,水和粮分开,猫狗通用。' AS answer, '食碗,不锈钢,304,生锈,食品级' AS tags, '不锈钢食碗话术' AS source_summary, 82 AS score
  UNION ALL SELECT 'pet_supplies_misc', '笼子折叠吗?不用了方便收纳吗', '亲,这款笼子是三秒折叠设计,不用了一按就折叠,厚度只有10厘米,塞床底门后都行。折叠后体积小,搬家携带方便。建议选折叠款,即使长期用,打扫时折叠也方便。如果不需要频繁收纳,固定款更稳更便宜。店里折叠款减30,小户型首选。您家空间够吗?不够的话折叠款最实用。' AS answer, '笼子,折叠,收纳,体积,小户型' AS tags, '笼子折叠话术' AS source_summary, 80 AS score
  UNION ALL SELECT 'pet_supplies_misc', '航空箱承重多少?大型犬能用吗', '亲,这款航空箱承重25公斤,中型犬如柯基法斗完全能用。如果是大型犬如金毛,建议拍大号航空箱,承重40公斤。但大型犬航空箱很大,自驾才能用,飞机托运有限制。短鼻犬如法斗斗牛不建议飞机托运,有窒息风险。您家狗多重什么品种?我帮您选合适的。店里大号款减30元。' AS answer, '航空箱,承重,大型犬,托运,短鼻犬' AS tags, '航空箱承重话术' AS source_summary, 84 AS score
  UNION ALL SELECT 'pet_supplies_misc', '猫砂盆材质安全吗?有甲醛吗', '亲,这款猫砂盆是PP材质,食品级,无甲醛无BPA,猫舔咬也没事。建议别买太便宜的塑料盆,可能用回收料,有异味和有害物质。辨别方法:闻气味,有刺鼻味的别买;看颜色,太鲜艳的可能加了色料。PP材质耐高温不变形,可以用热水烫洗消毒。店里PP盆减15,安全放心,别省这个钱。' AS answer, '猫砂盆,材质,甲醛,PP,安全' AS tags, '猫砂盆材质安全话术' AS source_summary, 83 AS score
  UNION ALL SELECT 'pet_supplies_misc', '双碗设计好吗?水和粮放一起', '亲,双碗设计方便,水和粮放一起,宠物吃饭喝水一站搞定。但缺点是水容易溅到粮里,粮泡软变质。建议选斜双碗款,水和粮分开远一点。或者用分体双碗,两个碗独立,溅水不影响。如果猫爱玩水,建议水和粮分开放,隔一米远。店里分体双碗减10元,水和粮不串味,更卫生。' AS answer, '双碗,水粮,分体,溅水,卫生' AS tags, '双碗设计话术' AS source_summary, 78 AS score
  UNION ALL SELECT 'pet_supplies_misc', '笼子能关多久?长期关猫行吗', '亲,笼子只适合临时关,不建议长期笼养猫。猫需要运动和探索,长期笼养会抑郁暴躁。笼子适合:第一,新猫隔离适应1到2周;第二,生病隔离养病;第三,来客人临时关。如果必须笼养,笼子至少80厘米,配吊床猫砂盆水碗玩具,每天放出来活动2小时以上。猫是自由动物,别长期关着。' AS answer, '笼子,笼养,隔离,抑郁,临时' AS tags, '笼子笼养话术' AS source_summary, 84 AS score
  UNION ALL SELECT 'pet_supplies_misc', '航空箱需要什么认证?航司认可吗', '亲,这款航空箱符合IATA国际航空运输协会标准,大部分航司认可。但每家航司要求略有不同,建议出行前咨询航司。一般要求:第一,硬壳箱体;第二,金属栅栏门;第三,通风孔四面;第四,活体动物标识;第五,水壶食盆。我店这款都满足,还有航司备案型号可选。短鼻犬如法斗不建议空运,有窒息风险。' AS answer, '航空箱,认证,IATA,航司,标识' AS tags, '航空箱认证话术' AS source_summary, 85 AS score
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;

-- ============ 5. 水族用品 pet_aquarium (30 条) ============
INSERT INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.59', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'pet_aquarium' AS code, '鱼缸会漏水吗?放客厅怕淹了' AS question, '亲,这款是一体成型超白玻璃,无胶缝,正常使用不会漏。但任何鱼缸都有爆裂风险,建议您:第一,放平整台面,不平会应力爆裂;第二,别放在地板上,万一漏水;第三,定期检查底部有无裂纹。我店有漏水包赔服务,30天内非人为漏水免费换新。配套垫子能缓冲应力,建议一起拍,减10元。' AS answer, '鱼缸,漏水,超白玻璃,爆裂,垫子' AS tags, '鱼缸防漏话术' AS source_summary, 88 AS score
  UNION ALL SELECT 'pet_aquarium', '加热棒温控准吗?会不会把鱼煮了', '亲理解担心,加热棒确实有煮鱼事故。这款是外置温控加双重传感器,精度正负1度,而且有超温断电保护,超过设定温度3度自动断电,双保险。但建议您:第一,配个独立温度计交叉验证;第二,新棒先空缸测试24小时;第三,别买杂牌加热棒,这是鱼命。店里温度计10块钱,建议一起拍,安全第一。' AS answer, '加热棒,温控,煮鱼,断电,传感器' AS tags, '加热棒温控话术' AS source_summary, 90 AS score
  UNION ALL SELECT 'pet_aquarium', '过滤器声音大吗?放卧室吵不吵', '亲,这款是静音水泵,实测噪音小于30分贝,相当于图书馆环境,卧室完全不影响睡眠。但任何过滤器都有水流声,建议您:第一,水位加到max线以上,水位低水泵会吸入空气产生噪音;第二,出水口贴着缸壁减少水花声;第三,定期清洗转子,脏了会响。如果实在敏感,我店有瀑布过滤,声音更小,要不要换?' AS answer, '过滤器,噪音,静音,卧室,水位' AS tags, '过滤器静音话术' AS source_summary, 85 AS score
  UNION ALL SELECT 'pet_aquarium', '鱼缸灯对鱼眼睛有害吗', '亲,这款是全光谱LED,模拟自然光,对鱼无伤害,反而促进发色。但任何灯都不能24小时开,鱼需要昼夜节律。建议每天开8到10小时,晚上关灯让鱼休息。别用普通家用灯,色温不对会让鱼紧张。这款灯带定时器,自动开关,免得您忘。店里还有日出款,渐亮渐暗模拟日出,鱼更舒服,凑单减20。' AS answer, '鱼缸灯,眼睛,全光谱,昼夜,定时' AS tags, '鱼缸灯安全话术' AS source_summary, 84 AS score
  UNION ALL SELECT 'pet_aquarium', '硝化细菌真假怎么分?加了没效果', '亲,硝化细菌确实水很深。真货液体有淡淡土腥味,假货是清水或刺鼻味。这款是科迪正品,有防伪码,我用了3年。但硝化细菌不是加了立刻水清,它是建立生态系统的,需要2到4周才稳定。建议您:第一,新缸加菌后别急着放鱼,养水7天;第二,配过滤棉加生化环,菌需要附着;第三,别一次洗滤材,会洗掉菌。店里三件套减20,开缸必备。' AS answer, '硝化细菌,真假,效果,开缸,养水' AS tags, '硝化细菌真假话术' AS source_summary, 87 AS score
  UNION ALL SELECT 'pet_aquarium', '鱼缸玻璃会爆吗?听说超白玻璃脆', '亲,超白玻璃确实比普通玻璃脆,透光率高但硬度低,但只要:第一,厚度达标,60厘米缸用8毫米以上;第二,底柜平整;第三,不磕碰边角最脆弱,正常用不会爆。这款是加厚超白,边角倒角处理,安全。建议您:第一,别用硬物敲缸壁;第二,别让小孩拍打;第三,定期检查边角有无裂纹。店里配套底垫减10元,建议一起拍。' AS answer, '鱼缸,爆裂,超白玻璃,厚度,边角' AS tags, '鱼缸爆裂话术' AS source_summary, 85 AS score
  UNION ALL SELECT 'pet_aquarium', '过滤棉怎么洗?会不会洗坏', '亲,过滤棉不能洗太干净!上面的脏东西其实是硝化细菌,洗没了水质会崩。建议您:第一,用原缸水洗,自来水氯气会杀菌;第二,轻轻搓洗别拧;第三,脏了就换新的,而不是反复洗,便宜耗材别省。生化环陶瓷环更不能洗,半年用原缸水涮一下就行。店里过滤棉10片装,够用半年,囤着划算。' AS answer, '过滤棉,清洗,硝化细菌,换新,生化环' AS tags, '过滤棉清洗话术' AS source_summary, 83 AS score
  UNION ALL SELECT 'pet_aquarium', 'CO2设备会不会漏气?有危险吗', '亲,CO2小瓶漏气没危险就是浪费,但大瓶漏气有窒息风险。这款是建设钢瓶,防爆防漏,有安全阀。但建议您:第一,别放高温环境,暴晒会增压;第二,定期涂肥皂水检查接口;第三,配电磁阀,夜间关灯关CO2,免得pH骤降。水草缸必备,但安全第一。店里电磁阀款减20,建议一起拍。' AS answer, 'CO2,漏气,钢瓶,电磁阀,安全' AS tags, 'CO2设备安全话术' AS source_summary, 85 AS score
  UNION ALL SELECT 'pet_aquarium', '鱼药安全吗?会不会把鱼毒死', '亲,鱼药按剂量用安全,过量确实会毒鱼。这款是日本黄粉,温和型,按1克每10升水用,病鱼药浴7天。但建议您:第一,药浴用单独容器,主缸下药会杀硝化菌;第二,药浴期间停食;第三,严重病鱼隔离治疗。预防大于治疗,建议平时备黄粉加亚甲基蓝加盐,常见病都能治。店里三件装减15,养鱼常备。' AS answer, '鱼药,安全,毒死,黄粉,剂量' AS tags, '鱼药安全话术' AS source_summary, 84 AS score
  UNION ALL SELECT 'pet_aquarium', '水草活体收到会死吗?运输几天', '亲,水草是耐运输的,比鱼好养,这款是湿发包装,能撑5到7天。但建议您:第一,收到先别急着种,泡水里恢复2小时;第二,黄叶烂叶剪掉;第三,新缸光照别太强,水草还没适应容易爆藻。如果有黑毛藻或融叶,7天内拍照我补发。建议搭配液肥,水草长得更旺,店里凑单减10元。' AS answer, '水草,活体,运输,成活,液肥' AS tags, '水草活体运输话术' AS source_summary, 82 AS score
  UNION ALL SELECT 'pet_aquarium', '鱼缸容量多大?能养几条鱼', '亲,这款鱼缸60乘30乘35厘米,约60升水。养鱼数量看鱼的大小,1厘米鱼需要1升水是基本法则。60升可以养:小型鱼如孔雀鱼15到20条;中型鱼如神仙鱼4到6条;大型鱼如金鱼3到4条。别养太多,密度大水质差鱼容易病。新手建议少养,先养好水再加鱼。店里60缸套装含过滤加热灯减50,开缸首选。' AS answer, '鱼缸,容量,养鱼数量,密度,法则' AS tags, '鱼缸容量话术' AS source_summary, 85 AS score
  UNION ALL SELECT 'pet_aquarium', '鱼食保质期多久?开封后能放多久', '亲,鱼食保质期2年,开封后建议3到6个月内喂完。开封后密封保存,避免阳光直射和高温,别放冰箱会吸潮变质。如果鱼食发霉或有异味,立即停喂,可能有毒。建议买小包装,新鲜不浪费。薄片饲料开封后更容易变质,颗粒料相对耐放。店里小包装50克装减5元,够吃2个月,小缸首选。' AS answer, '鱼食,保质期,开封,保存,变质' AS tags, '鱼食保质期话术' AS source_summary, 80 AS score
  UNION ALL SELECT 'pet_aquarium', '过滤器流量多大合适?我缸60升', '亲,过滤器流量建议是鱼缸水量的5到10倍,60升缸选流量300到600升每小时的过滤器。这款流量500升每小时,60升缸正合适。流量太小过滤不够水浑,流量太大水流急鱼游得累。小型鱼如孔雀建议5倍,大型鱼如金鱼建议8到10倍能吃能拉。店里500升过滤器减20元,60缸标配,要不要凑单?' AS answer, '过滤器,流量,60升,倍数,水流' AS tags, '过滤器流量话术' AS source_summary, 84 AS score
  UNION ALL SELECT 'pet_aquarium', '加热棒多少瓦?我缸60升够吗', '亲,加热棒功率看缸大小,一般1升水1到2瓦,60升缸建议100到150瓦。这款100瓦,60升缸在南方够用。如果在北方或冬天室内低于15度,建议拍150瓦,加热更快更稳。加热棒要完全浸没在水里,别露出水面会炸。建议配独立温度计,交叉验证水温。店里100瓦和150瓦款减15,选合适的。' AS answer, '加热棒,功率,瓦数,60升,温度' AS tags, '加热棒功率话术' AS source_summary, 82 AS score
  UNION ALL SELECT 'pet_aquarium', '造景材料会影响水质吗?会不会硬水', '亲,造景材料确实会影响水质。松皮石和木化石会硬水,适合养三湖慈鲷等硬水鱼。沉木会软水降pH,适合养灯鱼和南美鱼。青龙石微硬水,造景好看但要注意水质。建议根据鱼种选造景材料,别乱放。新造景材料要煮沸消毒或泡水一周再用。店里造景套装减20,含沉木加石头,要不要看看?养什么鱼告诉我,我帮您配。' AS answer, '造景,水质,硬水,沉木,石头' AS tags, '造景材料与水质话术' AS source_summary, 86 AS score
  UNION ALL SELECT 'pet_aquarium', '热带鱼冬天没加热棒会死吗', '亲,热带鱼水温低于20度会拒食,低于18度会冻死。冬天必须用加热棒,设定24到28度。别相信室温够,冬天室内10度鱼必死。加热棒是热带鱼保命装备,别省这个钱。建议买两个加热棒,一个主用一个备用,万一坏了另一个顶上。店里加热棒双支装减20,热带鱼必备双保险。冷水鱼如金鱼锦鲤不需要加热棒。' AS answer, '热带鱼,加热棒,冬天,水温,备用' AS tags, '热带鱼加热话术' AS source_summary, 88 AS score
  UNION ALL SELECT 'pet_aquarium', '鱼缸材质是玻璃还是亚克力?哪个好', '亲,这款是超白玻璃,透光率91%,比普通玻璃清晰,比亚克力耐刮不老化。亚克力轻便不易碎,但容易刮花,时间久发黄。玻璃重易碎但清晰耐用,是主流选择。建议60厘米以下选玻璃,大缸1米以上可以选亚克力,轻便安全。超白玻璃比普通玻璃贵但透光好,看鱼更清晰,值得多花点钱。店里超白缸减30元。' AS answer, '鱼缸,玻璃,亚克力,超白,材质' AS tags, '鱼缸材质对比话术' AS source_summary, 83 AS score
  UNION ALL SELECT 'pet_aquarium', '鱼食颗粒大小?小型鱼能吃吗', '亲,这款鱼食是微粒型,颗粒0.5到1毫米,小型鱼如孔雀灯鱼完全能吃。如果是大型鱼如鹦鹉鱼,建议拍大颗粒2到3毫米。颗粒太大鱼吃不下,太小大鱼不饱。建议根据鱼的大小选颗粒,别一种粮喂所有鱼。店里还有薄片型,漂浮水面适合上层鱼,缓沉型适合底层鱼。您养什么鱼?我帮您推荐合适的鱼食。' AS answer, '鱼食,颗粒,大小,小型鱼,微粒' AS tags, '鱼食颗粒话术' AS source_summary, 80 AS score
  UNION ALL SELECT 'pet_aquarium', '过滤器耗电吗?一直开费电吗', '亲,这款过滤器功率5瓦,24小时开一天0.12度电,一个月约3.6度,电费2块钱不到,非常省电。过滤器必须24小时开,关了硝化细菌会死,水质崩溃。加热棒费电些,100瓦一天2.4度,但加热棒是间歇工作,达到温度自动停,实际耗电减半。鱼缸灯8瓦一天开10小时,0.08度。整套鱼缸一个月电费10到20元。' AS answer, '过滤器,耗电,瓦数,24小时,电费' AS tags, '过滤器耗电话术' AS source_summary, 78 AS score
  UNION ALL SELECT 'pet_aquarium', '加热棒防爆吗?会不会炸', '亲,这款加热棒是石英玻璃管,防爆耐高温,而且有断电保护,离开水面自动断电,不会炸。但使用要注意:第一,加热棒必须完全浸没在水里,露出水面会炸;第二,换水时先拔电,别让加热棒露出水面干烧;第三,别用手摸工作中的加热棒会烫伤。建议选不锈钢外壳款,更防爆不碎。店里不锈钢款减15,有小孩和宠物的家庭首选。' AS answer, '加热棒,防爆,炸,断电,不锈钢' AS tags, '加热棒防爆话术' AS source_summary, 85 AS score
  UNION ALL SELECT 'pet_aquarium', '造景石种类多吗?能自己搭配吗', '亲,店里造景石有青龙石、松皮石、木化石、火山岩、鹅卵石等,可以自己搭配。建议:第一,一个缸用一种主石,别混太多乱;第二,石头大小有层次,大石打底小石点缀;第三,石头要洗或煮过再用,消毒去杂质。造景是艺术,没有标准答案,自己喜欢就好。店里造景石套装5斤装减15,混搭方便,要不要试试?' AS answer, '造景,石头,种类,搭配,消毒' AS tags, '造景石种类话术' AS source_summary, 80 AS score
  UNION ALL SELECT 'pet_aquarium', '冷水鱼需要什么设备?不用加热棒吧', '亲,冷水鱼如金鱼锦鲤不需要加热棒,冬天能耐低温。但需要过滤器和增氧泵,冷水鱼能吃能拉,过滤必须强。金鱼适合水温0到30度,冬天室内不用加热。但夏天水温超过30度要注意降温,鱼会缺氧。建议配温度计监控水温。冷水鱼比热带鱼好养,新手推荐。店里金鱼缸套装含过滤增氧减30,要不要看看?' AS answer, '冷水鱼,加热棒,过滤,增氧,温度' AS tags, '冷水鱼设备话术' AS source_summary, 82 AS score
  UNION ALL SELECT 'pet_aquarium', '鱼缸漏水了怎么办?能补吗', '亲,玻璃鱼缸漏水可以补,但要看漏水位置。如果是接缝漏,用专用玻璃胶重新打胶,24小时固化即可。如果是玻璃裂了,建议换新缸,补了也会再裂。建议:第一,发现漏水立即断电,防止漏电;第二,把鱼转移到临时容器;第三,擦干缸体检查漏水点。店里玻璃胶10元一支,补缝够用。如果缸老化了建议换新,别冒险。' AS answer, '鱼缸,漏水,补,玻璃胶,换新' AS tags, '鱼缸漏水补救话术' AS source_summary, 80 AS score
  UNION ALL SELECT 'pet_aquarium', '鱼食开封后怎么保存?需要冷藏吗', '亲,鱼食开封后不建议冷藏,冰箱湿度大反而容易发霉。正确保存:第一,密封夹夹紧袋口,挤出空气;第二,放在阴凉干燥处,避免阳光直射;第三,3到6个月内喂完保证新鲜。如果是薄片饲料,更容易吸潮,建议买小包装。如果鱼食发霉或有异味,立即停喂,发霉的鱼食有毒。店里小包装50克减5元,新鲜不浪费。' AS answer, '鱼食,开封,保存,冷藏,密封' AS tags, '鱼食开封保存话术' AS source_summary, 78 AS score
  UNION ALL SELECT 'pet_aquarium', '过滤器怎么清洗?多久洗一次', '亲,过滤器清洗分两部分:物理过滤棉每周洗一次,用原缸水轻轻搓洗,别用自来水会杀硝化菌。生化环陶瓷环半年洗一次,用原缸水涮一下就行,别搓洗。转子每月清洗一次,用棉签擦转子和轴,脏了会卡顿有噪音。切记:千万别一次洗所有滤材,会洗掉硝化细菌水质崩溃。建议分批洗,这周洗棉下周洗转子。' AS answer, '过滤器,清洗,滤材,硝化细菌,转子' AS tags, '过滤器清洗话术' AS source_summary, 84 AS score
  UNION ALL SELECT 'pet_aquarium', '加热棒温度范围多少?能调温吗', '亲,这款加热棒温度范围20到32度可调,旋钮设定,精度正负1度。热带鱼建议设定24到28度,具体看鱼种:灯鱼24到26度,七彩28到30度,孔雀22到26度。建议配独立温度计交叉验证,加热棒自带温度计可能不准。设定后别频繁调,温度波动对鱼不好。店里加热棒加温度计套装减15,安全又准确,要不要凑单?' AS answer, '加热棒,温度,调温,热带鱼,温度计' AS tags, '加热棒温度范围话术' AS source_summary, 82 AS score
  UNION ALL SELECT 'pet_aquarium', '水草需要什么灯?普通灯行吗', '亲,水草需要全光谱植物灯,普通LED灯不行,光谱不对水草不生长会烂。这款是水草专用全光谱灯,促进光合作用,水草长得旺。建议:阳性草强光每天8到10小时,阴性草中光6到8小时。别用家用日光灯,色温不对草会黄。如果养简单阴性草如水榕莫斯,中光灯就够。店里阳性草灯减20,水草缸必备。' AS answer, '水草,灯,全光谱,植物灯,光合' AS tags, '水草灯选择话术' AS source_summary, 85 AS score
  UNION ALL SELECT 'pet_aquarium', '鱼缸需要增氧泵吗?过滤器够吗', '亲,如果过滤器是瀑布或上滤,水流带氧,一般不需要额外增氧泵。但如果是滤桶,水流在桶内不接触空气,溶氧不足,建议配增氧泵。养鱼密度大或夏天高温,也建议增氧泵。养大型鱼如金鱼能吃能拉,增氧泵必备。判断方法:看鱼是否浮头呼吸,浮头就是缺氧。店里静音增氧泵减15,养鱼必备。' AS answer, '增氧泵,过滤器,溶氧,浮头,密度' AS tags, '增氧泵必要性话术' AS source_summary, 82 AS score
  UNION ALL SELECT 'pet_aquarium', '鱼缸放哪里好?不能放哪', '亲,鱼缸摆放建议:第一,放平整稳固的柜子或桌面,承重足够;第二,避免阳光直射,直射会长藻水温也会高;第三,远离空调和暖气,温度波动大鱼容易病;第四,别放卧室,过滤器声音影响睡眠。最佳位置是客厅靠墙,有自然光但不直射。鱼缸放好就别频繁移动,搬动容易爆缸。1米以上大缸要配专用底柜,承重安全。' AS answer, '鱼缸,摆放,位置,阳光,承重' AS tags, '鱼缸摆放位置话术' AS source_summary, 84 AS score
  UNION ALL SELECT 'pet_aquarium', '鱼缸水浑怎么办?新缸水白蒙蒙的', '亲,新缸水白蒙蒙的是正常的,叫"爆菌",是硝化细菌还没建立,水中有机物多细菌大量繁殖导致。解决方法:第一,别急着放鱼,先养水7到14天;第二,加硝化细菌加速建缸;第三,开过滤器24小时不停;第四,别喂太多,鱼粮残渣会加剧水浑。水变清说明硝化系统建立了,可以放鱼。如果老缸突然水浑,可能是过滤棉脏了或喂多了,洗棉停食两天就好。店里硝化细菌减10元,开缸必备。' AS answer, '鱼缸,水浑,爆菌,硝化细菌,养水' AS tags, '鱼缸水浑与开缸话术' AS source_summary, 87 AS score
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;
